#include <bits/stdc++.h>
using namespace std;

int N;
vector<vector<int>> adj;

struct State {
    int u, p, d;
};

int countAtDepth(int start, int banned, int target) {
    if (target < 0) return 0;
    if (target == 0) return 1;

    int cnt = 0;
    vector<State> st;
    st.push_back({start, banned, 0});

    while (!st.empty()) {
        State cur = st.back();
        st.pop_back();

        if (cur.d == target) {
            cnt++;
            continue;
        }

        for (int v : adj[cur.u]) {
            if (v == cur.p) continue;
            st.push_back({v, cur.u, cur.d + 1});
        }
    }

    return cnt;
}

pair<int, int> bfs(int start, vector<int>* parent = nullptr) {
    vector<int> dist(N + 1, -1);
    queue<int> q;

    dist[start] = 0;
    q.push(start);

    int far = start;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (dist[u] > dist[far]) far = u;

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (parent) (*parent)[v] = u;
                q.push(v);
            }
        }
    }

    return {far, dist[far]};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    adj.assign(N + 1, {});

    for (int i = 0; i < N - 1; i++) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    auto res1 = bfs(1);
    int A = res1.first;

    vector<int> parent(N + 1, 0);
    auto res2 = bfs(A, &parent);
    int B = res2.first;
    int D = res2.second;

    vector<int> path;
    for (int v = B; v != 0; v = parent[v]) {
        path.push_back(v);
    }
    reverse(path.begin(), path.end());

    long long ans = 0;

    if (D % 2 == 0) {
        int c = path[D / 2];
        int R = D / 2;

        long long S = 0, sumSq = 0;

        for (int nb : adj[c]) {
            int a = countAtDepth(nb, c, R - 1);
            S += a;
            sumSq += 1LL * a * a;
        }

        ans = (S * S - sumSq) / 2;
    } else {
        int c1 = path[D / 2];
        int c2 = path[D / 2 + 1];
        int R = D / 2;

        long long A1 = countAtDepth(c1, c2, R);
        long long B1 = countAtDepth(c2, c1, R);

        ans = A1 * B1;
    }

    cout << D + 1 << "\n" << ans << "\n";

    return 0;
}
